// Simulate MongoDB update operators
let product = {
  _id: 1,
  name: 'Wireless Headphones',
  price: 2499,
  stock: 10,
  views: 0,
  tags: ['audio', 'wireless'],
  discount: null
};

function applyUpdate(doc, update) {
  const result = { ...doc };
  if (update.$set) Object.assign(result, update.$set);
  if (update.$inc) {
    for (const [key, val] of Object.entries(update.$inc)) {
      result[key] = (result[key] || 0) + val;
    }
  }
  if (update.$push) {
    for (const [key, val] of Object.entries(update.$push)) {
      result[key] = [...(result[key] || []), val];
    }
  }
  if (update.$pull) {
    for (const [key, val] of Object.entries(update.$pull)) {
      result[key] = (result[key] || []).filter(item => item !== val);
    }
  }
  return result;
}

// Apply some updates
product = applyUpdate(product, { $set: { price: 2199 } });
console.log('After $set price:', product.price);

product = applyUpdate(product, { $inc: { views: 1, stock: -1 } });
console.log('After $inc — views:', product.views, 'stock:', product.stock);

product = applyUpdate(product, { $push: { tags: 'premium' } });
console.log('After $push:', product.tags);

product = applyUpdate(product, { $pull: { tags: 'wireless' } });
console.log('After $pull:', product.tags);
